/**
 * Returns the localised display name for a state, district, or block.
 * Falls back: requested language → Hindi → English key.
 */
export function getLocationDisplayName(
  name: string,
  type: 'state' | 'district' | 'block',
  lang: string,
): string {
  const code = lang.split('-')[0];

  // English → always return the original English key (no translation needed)
  if (code === 'en') return name;

  // Normalize whitespace before lookup. Some source names in stateDistrict.ts use
  // exotic Unicode spaces (e.g. U+202F narrow no-break space in "Maya Bazar"),
  // which would never match the regular-space keys in the maps below. JS `\s`
  // matches those Unicode spaces, so collapsing them to a plain space fixes the
  // mismatch. Try the raw name first so any (unlikely) exotic-space key still hits.
  const key = name.replace(/\s+/g, ' ').trim();

  const map =
    type === 'state'
      ? stateTranslations
      : type === 'district'
      ? districtTranslations
      : blockTranslations;
  // A block/tehsil very often shares its name with a district (the district HQ
  // block) or even a state. Many such blocks have no entry in blockTranslations
  // but ARE curated under districtTranslations/stateTranslations — fall back to
  // those so the name still renders natively instead of dropping to English.
  const entry =
    map[name] ?? map[key] ??
    (type === 'block'
      ? (districtTranslations[name] ?? districtTranslations[key] ?? stateTranslations[name] ?? stateTranslations[key])
      : undefined);
  if (!entry) return name;

  // For states: always fall back to Hindi (all states are translated in all langs).
  if (type === 'state') return entry[code] ?? entry['hi'] ?? name;

  // For districts/blocks:
  // - A curated translation for the exact language always wins.
  // - Marathi shares the Devanagari script with Hindi → the Hindi spelling is readable as-is.
  // - Every other script: transliterate the Hindi spelling into that script so the
  //   name renders natively instead of dropping back to English. Falls back to the
  //   English key only when no Hindi spelling exists to transliterate from.
  if (entry[code]) return entry[code] as string;
  if (code === 'mr') return entry['hi'] ?? name;
  const hindi = entry['hi'];
  if (hindi) return transliterateFromHindi(hindi, code);
  return name;
}
